import { DotOrbit, type DotOrbitProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#4a4a68", "#52527a", "#3a3a5c"];

interface ShaderDotOrbitProps
  extends Omit<DotOrbitProps, "frame" | "ref"> {}

function ShaderDotOrbitBase({
  speed = 1,
  colorBack = "#12121a",
  colors = NEUTRAL_COLORS,
  size = 1,
  spreading = 1,
  className,
  ...rest
}: ShaderDotOrbitProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-dot-orbit"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <DotOrbit
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colors={colors}
        size={size}
        spreading={spreading}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  size: {
    type: "number",
    min: 0.1,
    max: 3,
    step: 0.1,
    default: 1,
    description: "Size",
    hiddenFromList: false,
  },
  spreading: {
    type: "number",
    min: 0,
    max: 2,
    step: 0.1,
    default: 1,
    description: "Spreading",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","size","spreading","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  size: 1,
  spreading: 1,
  colorBack: "#12121a",
};

type ShaderDotOrbitElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderDotOrbitBase>;

const ShaderDotOrbitInner = forwardRef<
  HTMLDivElement,
  ShaderDotOrbitElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderDotOrbit>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderDotOrbitBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderDotOrbitBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderDotOrbit = Interactive.withSchema({
  Component: ShaderDotOrbitInner,
  componentName: "<ShaderDotOrbit>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
